 const[signalReport,setSignalReport]=useState<SignalReport|null>(null);

 const[cat,setCat]=useState<Catalogue>(initial),[view,setView]=useState('home'),[savedProfile,setSavedProfile]=useState<Profile>(()=>storedProfile('bn-profile',blank)),[journeyDraft,setJourneyDraft]=useState<Profile>(()=>storedProfile('bn-draft',storedProfile('bn-profile',blank))),[mode,setMode]=useState<SessionMode>(()=>sessionStorage.getItem('bn-mode')==='prototype'?'prototype':'guest'),[editDraft,setEditDraft]=useState<Profile|null>(null),[step,setStep]=useState(0),[look,setLook]=useState(()=>Math.max(0,journeyDraft.avatarId||0)),[custom,setCustom]=useState(()=>journeyDraft.title!==occupations[journeyDraft.avatarId||0]),[selected,setSelected]=useState('financial'),[scenario,setScenario]=useState('moderate'),[month,setMonth]=useState('2026-05'),[modal,setModal]=useState<Modal>(null),[toast,setToast]=useState(''),[tab,setTab]=useState('Tools'),[query,setQuery]=useState(''),[unmatched,setUnmatched]=useState<string[]>([]),[imported,setImported]=useState(false),[busy,setBusy]=useState(''),[rated,setRated]=useState<string[]>(()=>Object.entries(journeyDraft.mastery).filter(([,v])=>v>0).map(([id])=>id)),[completed,setCompleted]=useState<string[]>([]),[compare,setCompare]=useState<string[]>([]),[menu,setMenu]=useState(false),[cvText,setCvText]=useState(''),[dragging,setDragging]=useState(false),[lastRefresh,setLastRefresh]=useState(''),[focusPriority,setFocusPriority]=useState('Balanced'),[remote,setRemote]=useState<{key:string;matches:Match[]}|null>(null);
 const profile=view==='journey'?journeyDraft:savedProfile;
 function setProfile(update:React.SetStateAction<Profile>){(view==='journey'?setJourneyDraft:setSavedProfile)(update)}
 const personalLook=savedProfile.avatarId||0;
 const api=import.meta.env.VITE_BACKEND_ENABLED==='true';
 const fileRef=useRef<HTMLInputElement>(null);const dialogRef=useRef<HTMLElement>(null);const modalTrigger=useRef<HTMLElement|null>(null);
 const chosenSkills=cat.skills.filter(s=>s.id in profile.mastery);
 const requestKey=JSON.stringify({profile,month,scenario,revision:cat.evidence.retrieved_at});
