 const ranked=api&&remote?.key===requestKey?remote.matches:localRanked;
 const activeMatch=ranked.find(m=>m.role.id===selected)||ranked[0];
 const currentMatch=currentRole(cat,profile,month,scenario);const pathMatch=learningGoal==='current'?currentMatch:activeMatch;
 const periods=cat.evidence.months;
